export function vectorLength(t){return Math.sqrt(Math.pow(t.x,2)+Math.pow(t.y,2))}export function getAngle(t){return Math.atan((t[1].y-t[0].y)/(t[1].x-t[0].x))}export function rotateVector(t,r){return r?{x:Math.cos(r)*t.x-Math.sin(r)*t.y,y:Math.sin(r)*t.x+Math.cos(r)*t.y}:t}function o(t,r,n){var a=[{n:t[0]-n[0],lambda:r[0]},{n:t[1]-n[1],lambda:r[1]}],x=a[0].n*r[0]+a[1].n*r[1],y=a[0].lambda*r[0]+a[1].lambda*r[1];return-x/y}export function perpendicularFoot(t,r){var n=r[0],a=r[1],x={x:a.x-n.x,y:a.y-n.y},y=o([n.x,n.y],[x.x,x.y],[t.x,t.y]);return{x:n.x+y*x.x,y:n.y+y*x.y}}export function getDistancePointLine(t,r){var n=perpendicularFoot(t,r),a={x:n.x-t.x,y:n.y-t.y};return vectorLength(a)}export function getDistancePointPoint(t,r){return vectorLength({x:t.x-r.x,y:t.y-r.y})}
